.contact-form-container {
  max-width: 600px;
  margin: 30px auto;
  padding: 30px;
  background: #ffffff;
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
 
  h2 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: 25px;
    color: #2c2c2c;
  }
 
  .alert {
    margin-bottom: 20px;
    border-radius: 4px;
    font-size: 14px;
  }
 
  .contact-form {
    display: flex;
    flex-direction: column;
  }
 
  .form-group {
    margin-bottom: 18px;
    position: relative;
 
    .form-control {
      width: 100%;
      height: 45px;
      padding: 10px 12px;
      font-size: 14px;
      border: 1px solid #dcdcdc;
      border-radius: 4px;
      background-color: #f9f9f9;
      transition: all 0.2s ease;
 
      &::placeholder {
        color: #999;
        font-weight: 400;
      }
 
      &:focus {
        outline: none;
        border-color: #4caf50;
        background-color: #fff;
        box-shadow: 0 0 0 2px rgba(76, 175, 80, 0.15);
      }
    }
 
    .text-danger {
      display: block;
      margin-top: 5px;
      font-size: 12px;
      color: #d91f1c;
    }
  }
 
  .form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 20px;
 
    .button {
      min-width: 140px;
      height: 45px;
      font-size: 14px;
      border-radius: 4px;
      cursor: pointer;
      transition: all 0.2s ease;
    }
 
    .button-secondary {
      background: #f5f5f5;
      color: #555;
      border: 1px solid #ccc;
   
 
      &:hover {
        background: #eaeaea;
      }
    }
 
    .button-primary {
      background: #3e8fc5;
      color: #2656af;
      border: none;
 
      &:hover {
        background: #333;
      }
    }
  }
}
 